{
  "name": "SonicCritique AI",
  "description": "An advanced audio analysis tool that generates spectrograms and provides professional production feedback using Gemini AI, tailored for Studio One users and AI-assisted music creation.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface TimestampedFeedback {
  time: string;
  issue: string;
  suggestion: string;
  studioOneTip: string;
}

export interface CritiqueResult {
  overallScore: number;
  summary: string;
  tonalBalance: string;
  dynamics: string;
  stereoImage: string;
  timestampedFeedback: TimestampedFeedback[];
  generalSuggestions: string[];
}

export enum AnalysisStatus {
  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  GENERATING_VISUALS = 'GENERATING_VISUALS',
  ANALYZING_AI = 'ANALYZING_AI',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { CritiqueResult } from "../types";

const SYSTEM_INSTRUCTION = `You are a world-class mixing and mastering engineer with deep expertise in PreSonus Studio One. 
Your goal is to critique audio tracks that are often generated or assisted by AI. 
Provide a professional, technical, and constructive critique of the production quality.

Key Instructions:
1. Identify specific issues in tonal balance, dynamics, stereo imaging, and arrangement.
2. Provide precise timestamps (e.g., "0:45") for specific issues.
3. Offer concrete suggestions for improvement.
4. Include "Studio One Tips" for each specific issue (e.g., mention specific stock plugins like Pro EQ3, Fat Channel, or Pipeline XT where applicable).
5. Acknowledge that the track might be AI-generated and look for common "AI artifacts" like phase issues, unnatural transients, or repetitive structures.

Respond strictly in the provided JSON format.`;

export const analyzeAudio = async (base64Audio: string, mimeType: string): Promise<CritiqueResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Audio,
            mimeType: mimeType,
          },
        },
        {
          text: "Analyze this track. Focus on the mix and production quality. Remember I use PreSonus Studio One for mixing and I use AI to help make these songs."
        }
      ],
    },
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          overallScore: { type: Type.NUMBER, description: "Overall score out of 100" },
          summary: { type: Type.STRING },
          tonalBalance: { type: Type.STRING },
          dynamics: { type: Type.STRING },
          stereoImage: { type: Type.STRING },
          timestampedFeedback: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                time: { type: Type.STRING, description: "Timestamp like 0:30" },
                issue: { type: Type.STRING },
                suggestion: { type: Type.STRING },
                studioOneTip: { type: Type.STRING, description: "Specific tip for Studio One users" }
              },
              required: ["time", "issue", "suggestion", "studioOneTip"]
            }
          },
          generalSuggestions: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["overallScore", "summary", "tonalBalance", "dynamics", "stereoImage", "timestampedFeedback", "generalSuggestions"]
      }
    }
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result as CritiqueResult;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("The AI provided an invalid response format.");
  }
};

import React, { useEffect, useRef } from 'react';

interface SpectrogramProps {
  audioBuffer: AudioBuffer | null;
}

const Spectrogram: React.FC<SpectrogramProps> = ({ audioBuffer }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!audioBuffer || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;

    // Clear canvas
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(0, 0, width, height);

    const data = audioBuffer.getChannelData(0);
    const fftSize = 1024;
    const step = Math.floor(data.length / width);

    // This is a simplified visual representation of intensity over time/frequency
    // For a real spectrogram we'd need more complex FFT processing per slice
    // but we can simulate it for visual impact.
    for (let x = 0; x < width; x++) {
      const sliceStart = x * step;
      const sliceEnd = sliceStart + fftSize;
      if (sliceEnd > data.length) break;

      const slice = data.slice(sliceStart, sliceEnd);

      // Calculate a "pseudo-spectrum" for visual aesthetics
      for (let y = 0; y < height; y++) {
        const freqIndex = Math.floor((y / height) * (fftSize / 2));
        const amplitude = Math.abs(slice[freqIndex]) * 255;

        // Color mapping: Purple/Blue (low) to Orange/Yellow (high)
        const r = Math.min(255, amplitude * 2);
        const g = Math.min(255, amplitude * 1.2);
        const b = Math.min(255, amplitude * 4 + 50);

        ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
        ctx.fillRect(x, height - y, 1, 1);
      }
    }
  }, [audioBuffer]);

  return (
    <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800 shadow-2xl">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-lg font-semibold text-indigo-400">Audio Spectrogram</h3>
        <span className="text-xs text-slate-500 uppercase tracking-widest">Full Frequency Range</span>
      </div>
      <div className="relative overflow-hidden rounded-lg bg-black border border-slate-700">
        <canvas 
          ref={canvasRef} 
          width={1200} 
          height={300} 
          className="w-full h-auto block"
        />
        <div className="absolute top-0 left-0 h-full w-px bg-white/20 pointer-events-none" />
        <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent pointer-events-none" />
      </div>
      <div className="flex justify-between mt-2 text-[10px] text-slate-500 font-mono">
        <span>0:00</span>
        <span>Track Duration</span>
      </div>
    </div>
  );
};

export default Spectrogram;

import React from 'react';
import { CritiqueResult, TimestampedFeedback } from '../types';

interface CritiqueSectionProps {
  critique: CritiqueResult;
}

const FeedbackCard: React.FC<{ item: TimestampedFeedback }> = ({ item }) => (
  <div className="bg-slate-800/40 p-5 rounded-xl border-l-4 border-indigo-500 hover:bg-slate-800/60 transition-all">
    <div className="flex items-start justify-between mb-2">
      <span className="bg-indigo-600 text-white text-xs font-bold px-2 py-1 rounded">
        {item.time}
      </span>
      <div className="flex items-center space-x-2">
        <span className="text-xs text-slate-400 italic">Studio One Expert Tip</span>
      </div>
    </div>
    <h4 className="font-semibold text-slate-100 mb-1">{item.issue}</h4>
    <p className="text-slate-300 text-sm mb-4 leading-relaxed">{item.suggestion}</p>
    <div className="bg-indigo-950/30 p-3 rounded-lg border border-indigo-900/50 text-indigo-200 text-xs">
      <strong>Pro Tip:</strong> {item.studioOneTip}
