);

const CritiqueSection: React.FC<CritiqueSectionProps> = ({ critique }) => {
  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-400';
    if (score >= 60) return 'text-yellow-400';
    return 'text-red-400';
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 bg-slate-900/50 p-6 rounded-2xl border border-slate-800 shadow-xl">
          <div className="flex items-center space-x-4 mb-4">
            <div className={`text-5xl font-black ${getScoreColor(critique.overallScore)}`}>
              {critique.overallScore}
            </div>
            <div>
              <h2 className="text-xl font-bold">Overall Production Grade</h2>
              <p className="text-slate-400 text-sm">Comprehensive AI Analysis</p>
            </div>
          </div>
          <p className="text-slate-200 leading-relaxed italic border-t border-slate-800 pt-4 mt-4">
            "{critique.summary}"
          </p>
        </div>

        <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800 shadow-xl space-y-4">
          <h3 className="font-bold text-slate-400 uppercase text-xs tracking-widest">General Health</h3>
          <div>
            <div className="text-xs text-slate-500 mb-1">Tonal Balance</div>
            <div className="text-sm font-medium">{critique.tonalBalance}</div>
          </div>
          <div>
            <div className="text-xs text-slate-500 mb-1">Dynamics</div>
            <div className="text-sm font-medium">{critique.dynamics}</div>
          </div>
          <div>
            <div className="text-xs text-slate-500 mb-1">Stereo Imaging</div>
            <div className="text-sm font-medium">{critique.stereoImage}</div>
          </div>
        </div>
      </section>

      <section>
        <h3 className="text-2xl font-bold mb-6 flex items-center">
          <span className="bg-indigo-500 w-2 h-8 rounded-full mr-3" />
          Timeline Critique
        </h3>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {critique.timestampedFeedback.map((item, idx) => (
            <FeedbackCard key={idx} item={item} />
          ))}
        </div>
      </section>

      <section className="bg-indigo-900/20 p-8 rounded-3xl border border-indigo-500/30">
        <h3 className="text-xl font-bold mb-4 text-indigo-300">Strategic Roadmap for Studio One</h3>
        <ul className="space-y-3">
          {critique.generalSuggestions.map((suggestion, idx) => (
            <li key={idx} className="flex items-start">
              <span className="text-indigo-500 mr-3 mt-1">✦</span>
              <span className="text-slate-300">{suggestion}</span>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
