${critique.generalSuggestions.map(s => `- ${s}`).join('\n')}

---------------------------------------------
Generated by SonicCritique AI
Professional Engineering Assistance for Studio One Users
    `.trim();

    const blob = new Blob([reportText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileName ? fileName.split('.')[0] : 'analysis'}-critique.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
