              </svg>
              <span>DOWNLOAD REPORT</span>
            </button>
          </div>
          <div className="flex items-center space-x-4 mb-4">
            <div className={`text-5xl font-black ${getScoreColor(critique.overallScore)}`}>
              {critique.overallScore}
            </div>
            <div>
              <h2 className="text-xl font-bold">Overall Production Grade</h2>
              <p className="text-slate-400 text-sm">Comprehensive AI Analysis</p>
            </div>
          </div>
