              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-8">
              {[
                { title: 'Studio One Optimization', icon: '🎹' },
                { title: 'Spectrogram Visuals', icon: '📊' },
                { title: 'Timestamped Issues', icon: '⏱️' }
              ].map((feature, i) => (
                <div key={i} className="bg-slate-900/40 p-4 rounded-xl border border-slate-800 text-sm font-medium">
                  <span className="block text-2xl mb-1">{feature.icon}</span>
                  {feature.title}
                </div>
              ))}
            </div>
          </div>
        )}

        {(status !== AnalysisStatus.IDLE && status !== AnalysisStatus.ERROR) && (
          <div className="space-y-12">
            {/* Loading States */}
            {status !== AnalysisStatus.SUCCESS && (
              <div className="max-w-md mx-auto text-center space-y-6 py-20">
                <div className="relative">
                  <div className="w-20 h-20 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mx-auto" />
                  <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 font-bold text-indigo-500">
                    {status === AnalysisStatus.COMPARING ? "VS" : "AI"}
                  </div>
                </div>
                <div>
                  <h3 className="text-xl font-bold text-white mb-2">
                    {status === AnalysisStatus.UPLOADING && "Processing File..."}
                    {status === AnalysisStatus.GENERATING_VISUALS && "Mapping Frequencies..."}
                    {status === AnalysisStatus.ANALYZING_AI && "Expert Engineer Reviewing..."}
                    {status === AnalysisStatus.COMPARING && "Comparing Versions..."}
                  </h3>
                  <p className="text-slate-400 animate-pulse">
                    {status === AnalysisStatus.COMPARING 
                      ? "Evaluating improvements and tracking progress..." 
                      : status === AnalysisStatus.ANALYZING_AI
                        ? "Listening to transients and stereo width..." 
                        : "Decoding audio data for analysis..."}
                  </p>
                </div>
              </div>
            )}

            {/* Success View */}
            {status === AnalysisStatus.SUCCESS && critique && (
              <>
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                  <div>
                    <h2 className="text-3xl font-extrabold text-white mb-2">{fileName}</h2>
                    <p className="text-slate-400">
                      {isComparisonMode ? 'Comparison Report Generated' : 'Initial Analysis Complete • Professional Grade Report'}
                    </p>
                  </div>
                  <div className="flex space-x-2">
                    <button 
                      onClick={reset}
                      className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full text-sm font-bold transition-colors"
                    >
                      Start Fresh
                    </button>
                    {!isComparisonMode && (
                      <button 
                        onClick={startComparison}
                        className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full text-sm font-bold transition-all shadow-lg shadow-indigo-500/20"
                      >
                        Upload Comparison
