          </p>
        </div>
      </footer>

      {/* Single Global File Input */}
      <input 
        type="file" 
        ref={globalFileInputRef} 
        onChange={handleFileChange} 
        className="hidden" 
        accept="audio/*" 
      />
    </div>
  );
};

