import { GoogleGenAI, Type, Chat } from "@google/genai";
import { CritiqueResult } from "../types";

const BASE_SYSTEM_INSTRUCTION = `You are a world-class mixing and mastering engineer with deep expertise in PreSonus Studio One. 
Your goal is to critique audio tracks that are often generated or assisted by AI. 
Provide a professional, technical, and constructive critique of the production quality.`;

const CRITIQUE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    overallScore: { type: Type.NUMBER, description: "Overall score out of 100" },
    summary: { type: Type.STRING },
    tonalBalance: { type: Type.STRING },
    dynamics: { type: Type.STRING },
    stereoImage: { type: Type.STRING },
    timestampedFeedback: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          time: { type: Type.STRING, description: "Timestamp like 0:30" },
          issue: { type: Type.STRING },
          suggestion: { type: Type.STRING },
          studioOneTip: { type: Type.STRING, description: "Specific tip for Studio One users" }
        },
        required: ["time", "issue", "suggestion", "studioOneTip"]
      }
    },
    thirdPartyPlugins: {
      type: Type.ARRAY,
      description: "Suggestions for 3rd party plugins that would solve specific issues in the track.",
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING, description: "Plugin name (e.g., FabFilter Pro-Q 3)" },
          reason: { type: Type.STRING, description: "Why this specific plugin is better for this specific track's needs" },
          url: { type: Type.STRING, description: "Direct URL to the product page" }
        },
        required: ["name", "reason", "url"]
      }
    },
    generalSuggestions: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    comparisonSummary: { type: Type.STRING, description: "If this is a comparison, summarize the changes vs the previous version" },
    improvements: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of things that got better" },
    remainingIssues: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of things that still need work" },
    scoreChange: { type: Type.NUMBER, description: "The difference in score compared to previous version" }
  },
  required: ["overallScore", "summary", "tonalBalance", "dynamics", "stereoImage", "timestampedFeedback", "generalSuggestions"]
};

export const analyzeAudio = async (base64Audio: string, mimeType: string, previousCritique?: CritiqueResult): Promise<CritiqueResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let prompt = "Analyze this track. Focus on the mix and production quality. Remember I use PreSonus Studio One for mixing and I use AI to help make these songs.";
  let systemInstruction = BASE_SYSTEM_INSTRUCTION + `
Key Instructions:
1. Identify specific issues in tonal balance, dynamics, stereo imaging, and arrangement.
2. Provide precise timestamps (e.g., "0:45") for specific issues.
3. Offer concrete suggestions for improvement using Studio One stock tools.
4. Additionally, suggest exactly 2 or 3 professional 3rd party plugins (like FabFilter, iZotope, Waves, Soundtoys) that would elevate the track, including why they specifically help and their official URLs.
5. Respond strictly in the provided JSON format.`;

  if (previousCritique) {
    systemInstruction += `
COMPARISON MODE: 
This is a new version of a song you previously critiqued. 
Previous Score: ${previousCritique.overallScore}
Previous Summary: ${previousCritique.summary}
Previous Suggestions: ${previousCritique.generalSuggestions.join(', ')}

Your task is to:
1. Compare this new version to the previous one based on your previous critique.
2. Be honest: did the user actually fix the issues? Did they overcompensate?
3. Calculate the scoreChange (positive or negative).
4. Fill out the comparisonSummary, improvements, and remainingIssues fields.`;

    prompt = "Analyze this new version and compare it to the previous critique I provided. Tell me honestly if it's better or worse and what changed.";
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Audio,
            mimeType: mimeType,
          },
        },
        {
          text: prompt
        }
      ],
    },
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: CRITIQUE_SCHEMA
    }
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result as CritiqueResult;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("The AI provided an invalid response format.");
  }
};

export const createChatSession = (critique: CritiqueResult): Chat => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `You are a helpful mixing and mastering engineer. 
The user has just received an analysis for their track with the following details:
Overall Score: ${critique.overallScore}
Summary: ${critique.summary}
Tonal Balance: ${critique.tonalBalance}
Dynamics: ${critique.dynamics}
Stereo Image: ${critique.stereoImage}
Suggestions: ${critique.generalSuggestions.join(', ')}

Answer questions technical questions about this critique, suggest specific PreSonus Studio One settings, or elaborate on the 3rd party plugins suggested. Keep your answers technical, professional, and encouraging.`,
    },
  });
};

import React, { useState, useRef, useEffect } from 'react';
import { Chat } from '@google/genai';
import { ChatMessage } from '../types';

interface ChatInterfaceProps {
  session: Chat;
  isOpen: boolean;
  onClose: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ session, isOpen, onClose }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const response = await session.sendMessageStream({ message: userMsg });
      let fullText = '';

      // Append a placeholder for the model response
      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of response) {
        const textChunk = chunk.text || '';
        fullText += textChunk;
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullText };
          return updated;
        });
      }
    } catch (error) {
      console.error('Chat error:', error);
      setMessages(prev => [...prev, { role: 'model', text: 'Sorry, I encountered an error processing that request.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed bottom-6 right-6 w-96 h-[600px] bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl flex flex-col z-[100] animate-in slide-in-from-bottom-10 duration-300">
      <div className="p-4 border-b border-slate-800 flex items-center justify-between bg-indigo-950/20 rounded-t-3xl">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20">
              <path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" />
              <path d="M15 7v2a4 4 0 01-4 4H9.828l-1.766 1.767c.28.149.599.233.938.233h2l3 3v-3h2a2 2 0 002-2V9a2 2 0 00-2-2h-1z" />
            </svg>
          </div>
          <div>
            <h3 className="text-sm font-bold">Mixing Engineer Chat</h3>
            <p className="text-[10px] text-slate-400">Powered by Gemini AI</p>
          </div>
        </div>
        <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors p-1">
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center py-10 px-4">
            <p className="text-slate-500 text-sm">Ask me about specific parts of the analysis, Studio One settings, or plugin recommendations!</p>
          </div>
        )}
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-slate-800 text-slate-100 rounded-tl-none'}`}>
              {msg.text}
            </div>
          </div>
        ))}
        {isTyping && messages[messages.length-1].text === '' && (
          <div className="flex justify-start">
            <div className="bg-slate-800 p-3 rounded-2xl rounded-tl-none flex space-x-1">
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-4 border-t border-slate-800 bg-slate-900/50 rounded-b-3xl">
        <div className="relative">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask a follow-up..."
            className="w-full bg-slate-800 border border-slate-700 rounded-xl py-2.5 px-4 pr-12 text-sm focus:outline-none focus:border-indigo-500 transition-colors"
          />
          <button 
            type="submit"
            className="absolute right-2 top-1/2 -translate-y-1/2 text-indigo-500 hover:text-indigo-400 p-1"
          >
            <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
              <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
            </svg>
          </button>
        </div>
      </form>
    </div>
  );
};

