import React, { useState, useCallback, useRef, useMemo } from 'react';
import { AnalysisStatus, CritiqueResult } from './types';
import { analyzeAudio, createChatSession } from './services/geminiService';
import Spectrogram from './components/Spectrogram';
import CritiqueSection from './components/CritiqueSection';
import ChatInterface from './components/ChatInterface';

const App: React.FC = () => {
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [critique, setCritique] = useState<CritiqueResult | null>(null);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [fileName, setFileName] = useState<string | null>(null);
  const [isComparisonMode, setIsComparisonMode] = useState(false);
  const [isChatOpen, setIsChatOpen] = useState(false);

  const globalFileInputRef = useRef<HTMLInputElement>(null);

  // Initialize chat session memoized to avoid re-creation on every render
  const chatSession = useMemo(() => {
    if (critique) return createChatSession(critique);
    return null;
  }, [critique]);

  const processAudioFile = useCallback(async (file: File, isComparing: boolean = false) => {
    try {
      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.UPLOADING);
      setFileName(file.name);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => {
          const result = reader.result as string;
          resolve(result.split(',')[1]);
        };
        reader.readAsDataURL(file);
      });

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const arrayBuffer = await file.arrayBuffer();
      const decodedBuffer = await audioCtx.decodeAudioData(arrayBuffer);
      setAudioBuffer(decodedBuffer);

      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.ANALYZING_AI);
      const base64Audio = await base64Promise;

      const result = await analyzeAudio(base64Audio, file.type, isComparing ? critique || undefined : undefined);

      // We set isComparisonMode to true if we just finished a comparison upload
      if (isComparing) {
        setIsComparisonMode(true);
      }

      setCritique(result);
      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred during analysis.");
      setStatus(AnalysisStatus.ERROR);
    }
  }, [critique]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // If we already have a critique, this upload is a comparison
      const isComparing = critique !== null;
      processAudioFile(file, isComparing);
      e.target.value = '';
    }
  };

  const triggerUpload = () => {
    globalFileInputRef.current?.click();
  };

  const reset = () => {
    setStatus(AnalysisStatus.IDLE);
    setCritique(null);
    setAudioBuffer(null);
    setError(null);
    setFileName(null);
    setIsComparisonMode(false);
    setIsChatOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 relative overflow-x-hidden">
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={reset}>
            <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" />
              </svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight">Sonic<span className="text-indigo-500">Critique</span> AI</h1>
          </div>
          <div className="flex items-center space-x-4">
            {critique && (
              <button 
                onClick={() => setIsChatOpen(prev => !prev)}
                className={`flex items-center space-x-2 px-4 py-1.5 rounded-full text-xs font-bold transition-all ${isChatOpen ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
              >
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                   <path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" />
                </svg>
                <span>{isChatOpen ? 'CLOSE CHAT' : 'CHAT WITH ENGINEER'}</span>
              </button>
            )}
            <div className="hidden md:flex items-center space-x-2">
              <span className="text-xs text-slate-400 font-mono flex items-center">
                <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse" />
                Studio One Integrated
              </span>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-12">
        {status === AnalysisStatus.IDLE && (
          <div className="max-w-2xl mx-auto text-center space-y-8 animate-in zoom-in duration-500">
            <div className="space-y-4">
              <h2 className="text-4xl md:text-5xl font-extrabold text-white">
                Elevate your <span className="bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-purple-400">Production</span>
              </h2>
              <p className="text-slate-400 text-lg leading-relaxed">
                Upload your tracks for professional-grade critiques tailored for Studio One. 
                Our AI analyzes tonal balance, dynamics, and stereo image to help you perfect your mix.
              </p>
            </div>

            <div 
              onClick={triggerUpload}
              className="group relative cursor-pointer p-12 rounded-3xl border-2 border-dashed border-slate-800 bg-slate-900/30 hover:bg-slate-900/50 hover:border-indigo-500/50 transition-all duration-300"
            >
              <div className="flex flex-col items-center">
                <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-indigo-600 transition-colors">
                  <svg className="w-8 h-8 text-indigo-400 group-hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold mb-2">Drop your audio here</h3>
                <p className="text-slate-500">Supports WAV, MP3, and AIFF</p>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-8">
              {['Studio One Optimized', 'Visual Spectrograms', 'Unlimited Comparisons'].map((feature, i) => (
                <div key={i} className="bg-slate-900/40 p-4 rounded-xl border border-slate-800 text-sm font-medium text-slate-300">
                  {feature}
                </div>
              ))}
            </div>
          </div>
        )}

        {(status !== AnalysisStatus.IDLE && status !== AnalysisStatus.ERROR) && (
          <div className="space-y-12">
            {status !== AnalysisStatus.SUCCESS && (
              <div className="max-w-md mx-auto text-center space-y-6 py-20">
                <div className="relative">
                  <div className="w-20 h-20 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mx-auto" />
                  <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 font-bold text-indigo-500">
                    {status === AnalysisStatus.COMPARING ? "VS" : "AI"}
                  </div>
                </div>
                <h3 className="text-xl font-bold text-white mb-2">
                  {status === AnalysisStatus.UPLOADING && "Processing File..."}
                  {status === AnalysisStatus.GENERATING_VISUALS && "Mapping Frequencies..."}
                  {status === AnalysisStatus.ANALYZING_AI && "Expert Review in Progress..."}
                  {status === AnalysisStatus.COMPARING && "Evaluating Changes..."}
                </h3>
              </div>
            )}

            {status === AnalysisStatus.SUCCESS && critique && (
              <div className="animate-in fade-in slide-in-from-bottom-6 duration-700">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-800 pb-8 mb-8">
                  <div>
                    <h2 className="text-3xl font-extrabold text-white mb-1">{fileName}</h2>
                    <p className="text-slate-500 font-medium">
                      {isComparisonMode ? 'Comparison Report Generated' : 'Initial Engineering Review Complete'}
                    </p>
                  </div>
                  <div className="flex space-x-3">
                    <button onClick={reset} className="px-5 py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-sm font-bold transition-all">
                      Analyze New Track
                    </button>
                    <button onClick={triggerUpload} className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-emerald-500/20">
                      Upload Revision
                    </button>
                  </div>
                </div>

                <CritiqueSection 
                  critique={critique} 
                  fileName={fileName} 
                  onCompare={triggerUpload}
                  isComparison={isComparisonMode}
                />

                <Spectrogram audioBuffer={audioBuffer} />

                <div className="pt-12 text-center">
                   <button 
                    onClick={() => setIsChatOpen(true)}
                    className="inline-flex items-center space-x-3 bg-indigo-600/10 border border-indigo-500/30 text-indigo-400 px-8 py-4 rounded-2xl hover:bg-indigo-600/20 transition-all font-bold"
                  >
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                      <path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" />
                    </svg>
                    <span>Have follow-up questions? Ask our Engineer!</span>
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {status === AnalysisStatus.ERROR && (
          <div className="max-w-lg mx-auto bg-red-950/20 border border-red-500/30 p-8 rounded-3xl text-center space-y-6">
            <h2 className="text-xl font-bold text-red-400">Analysis Failed</h2>
            <p className="text-slate-400">{error}</p>
            <button onClick={reset} className="w-full py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold transition-colors">
              Try Again
            </button>
          </div>
        )}
      </main>

      <footer className="border-t border-slate-900 bg-slate-950 py-12">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <p className="text-slate-600 text-sm">
            Tuned for PreSonus Studio One. Always comparing your progress.
          </p>
        </div>
      </footer>

      {/* Persistent Chat Section */}
      {chatSession && (
        <ChatInterface 
          session={chatSession} 
          isOpen={isChatOpen} 
          onClose={() => setIsChatOpen(false)} 
        />
      )}

      {/* Single Global File Input */}
      <input 
        type="file" 
        ref={globalFileInputRef} 
        onChange={handleFileChange} 
        className="hidden" 
        accept="audio/*" 
      />
    </div>
  );
};

