    if (score >= 80) return 'text-green-400';
    if (score >= 60) return 'text-yellow-400';
    return 'text-red-400';
  };

  const downloadReport = () => {
    const reportText = `
SONICCRITIQUE AI - ${isComparison ? 'COMPARISON' : 'PRODUCTION'} ANALYSIS REPORT
=============================================
File: ${fileName || 'Untitled Track'}
${isComparison ? `Comparison Result: ${critique.scoreChange && critique.scoreChange >= 0 ? '+' : ''}${critique.scoreChange} points change` : ''}
Overall Production Grade: ${critique.overallScore}/100

${isComparison ? `COMPARISON SUMMARY:
"${critique.comparisonSummary}"

IMPROVEMENTS:
${critique.improvements?.map(i => `- ${i}`).join('\n')}

STILL NEEDS WORK:
${critique.remainingIssues?.map(i => `- ${i}`).join('\n')}
` : ''}

SUMMARY:
"${critique.summary}"

TIMELINE CRITIQUE:
${critique.timestampedFeedback.map(item => `
[${item.time}] ${item.issue}
Suggestion: ${item.suggestion}
Studio One Tip: ${item.studioOneTip}
`).join('\n')}

${critique.thirdPartyPlugins?.length ? `RECOMMENDED 3RD PARTY PLUGINS:
${critique.thirdPartyPlugins.map(p => `- ${p.name}: ${p.reason} (${p.url})`).join('\n')}
` : ''}

---------------------------------------------
Generated by SonicCritique AI
 Professional Studio One Workflow Support
    `.trim();

    const blob = new Blob([reportText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileName ? fileName.split('.')[0] : 'analysis'}-${isComparison ? 'comparison' : 'critique'}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-8">
