      <section className="bg-indigo-900/10 p-8 rounded-3xl border border-indigo-500/20">
        <h3 className="text-xl font-bold mb-4 text-indigo-300">Strategic Roadmap for Studio One</h3>
        <ul className="space-y-3">
          {critique.generalSuggestions.map((suggestion, idx) => (
            <li key={idx} className="flex items-start">
              <span className="text-indigo-500 mr-3 mt-1">✦</span>
              <span className="text-slate-300">{suggestion}</span>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
};

