import { GoogleGenAI, Type, Chat } from "@google/genai";
import { CritiqueResult } from "../types";

const USER_VST_LIBRARY = `
4Front Piano x64.vst, Attracktive.vst3, Bertom_DenoiserClassic.vst3, DelaySon.vst3, Proteus.vst3, STL ControlHub.vst3, TAL-Chorus-LX.vst3, ACE Bridge 2.vst3, ACE Bridge ARA.vst3, ACE Bridge.vst3, Amped - Block Letter.vst3, Amped - Fluff 2C.vst3, Amped - Humble.vst3, Amped - Roots.vst3, Amped - Volcano.vst3, amplistortion2_64bits.vst3, Auburn Sounds Panagement 2-64.vst3, BFDPlayer.vst3, Boogex.vst3, bx_blackdist2.vst3, bx_bluechorus2.vst3, bx_boom.vst3, bx_cleansweep V2.vst3, bx_distorange.vst3, bx_greenscreamer.vst3, bx_masterdesk Classic.vst3, bx_megasingle.vst3, bx_metal2.vst3, bx_meter.vst3, bx_opto Pedal.vst3, bx_rockrack V3 Player.vst3, bx_shredspread.vst3, bx_solo.vst3, bx_subfilter.vst3, bx_subsynth.vst3, bx_tuner.vst3, bx_yellowdrive.vst3, Clear.vst3, CUBE.vst3, elysia niveau filter.vst3, Emissary.vst3, Kontakt 7.vst3, Kontakt 8.vst3, LoudMax.vst3, MT-PowerDrumKit.vst3, NadIR.vst3, NAM Universal.vst3, PlaceIt.vst3, Puncher2Lite.vst3, RRS EQ560 Free VST3_64.vst3, ShapeIt.vst3, smartEQ3.vst3, SOL.vst3, soothe2_x64.vst3, SPL Free Ranger.vst3, STL Ignite - AmpHub.vst3, Youlean Loudness Meter 2.vst3
`;

const BASE_SYSTEM_INSTRUCTION = `You are a world-class mixing and mastering engineer with deep expertise in PreSonus Studio One. 
Your goal is to critique audio tracks that are often generated or assisted by AI. 
Provide a professional, technical, and constructive critique of the production quality.

The user has the following VST plugins ALREADY INSTALLED in their library:
${USER_VST_LIBRARY}

When providing feedback, you MUST check if any of the user's existing plugins can solve the problems you identify. Prioritize recommending their existing tools over buying new ones.`;

const CRITIQUE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    overallScore: { type: Type.NUMBER, description: "Overall score out of 100" },
    summary: { type: Type.STRING },
    tonalBalance: { type: Type.STRING },
    dynamics: { type: Type.STRING },
    stereoImage: { type: Type.STRING },
    timestampedFeedback: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          time: { type: Type.STRING, description: "Timestamp like 0:30" },
          issue: { type: Type.STRING },
          suggestion: { type: Type.STRING },
          studioOneTip: { type: Type.STRING, description: "Specific tip for Studio One users" }
        },
        required: ["time", "issue", "suggestion", "studioOneTip"]
      }
    },
    libraryPluginSuggestions: {
      type: Type.ARRAY,
      description: "Specific recommendations using the user's ALREADY OWNED plugins from the provided list.",
      items: {
        type: Type.OBJECT,
        properties: {
          pluginName: { type: Type.STRING, description: "The name of the plugin from the user's list" },
          application: { type: Type.STRING, description: "Exactly how and where to use it on this track" }
        },
        required: ["pluginName", "application"]
      }
    },
    thirdPartyPlugins: {
      type: Type.ARRAY,
      description: "Suggestions for 3rd party plugins the user DOES NOT have yet, only if they offer something their library can't.",
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING, description: "Plugin name" },
          reason: { type: Type.STRING, description: "Why this specifically is needed beyond what they have" },
          url: { type: Type.STRING, description: "Direct URL" }
        },
        required: ["name", "reason", "url"]
      }
    },
    generalSuggestions: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    comparisonSummary: { type: Type.STRING },
    improvements: { type: Type.ARRAY, items: { type: Type.STRING } },
    remainingIssues: { type: Type.ARRAY, items: { type: Type.STRING } },
    scoreChange: { type: Type.NUMBER }
  },
  required: ["overallScore", "summary", "tonalBalance", "dynamics", "stereoImage", "timestampedFeedback", "generalSuggestions", "libraryPluginSuggestions"]
};

export const analyzeAudio = async (base64Audio: string, mimeType: string, previousCritique?: CritiqueResult): Promise<CritiqueResult> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let prompt = "Analyze this track. Focus on technical production. Reference my specific VST library in your suggestions.";
  let systemInstruction = BASE_SYSTEM_INSTRUCTION + `
Key Instructions:
1. Identify specific issues in tonal balance, dynamics, and stereo imaging.
2. Cross-reference issues with the user's plugin library (${USER_VST_LIBRARY}).
3. Provide a 'libraryPluginSuggestions' list mapping issues to their owned VSTs.
4. Only suggest new 3rd party plugins in 'thirdPartyPlugins' if their library is missing a critical tool (like a specific character compressor or high-end limiter).`;

  if (previousCritique) {
    systemInstruction += `
COMPARISON MODE: 
Previous Score: ${previousCritique.overallScore}
Previous Suggestions: ${previousCritique.generalSuggestions.join(', ')}
Compare and see if the user used their library tools effectively as previously suggested.`;

    prompt = "Analyze this new version and compare it to the previous critique. Did the use of my library plugins improve the result?";
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Audio, mimeType: mimeType } },
        { text: prompt }
      ],
    },
    config: {
      systemInstruction: systemInstruction,
      responseMimeType: "application/json",
      responseSchema: CRITIQUE_SCHEMA
    }
  });

  try {
    const text = response.text || '{}';
    return JSON.parse(text) as CritiqueResult;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    throw new Error("The AI provided an invalid response format.");
  }
};

export const createChatSession = (critique: CritiqueResult): Chat => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `You are a helpful mixing and mastering engineer. 
