                  <div className="pt-12 text-center print:hidden">
                     <button 
                      onClick={() => setIsChatOpen(true)}
                      className="inline-flex items-center space-x-3 bg-indigo-600/10 border border-indigo-500/30 text-indigo-400 px-8 py-4 rounded-2xl hover:bg-indigo-600/20 transition-all font-bold"
                    >
                      <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
                      <span>Ask our Engineer about this revision</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {status === AnalysisStatus.ERROR && (
            <div className="max-w-lg mx-auto bg-red-950/20 border border-red-500/30 p-8 rounded-3xl text-center space-y-6">
              <h2 className="text-xl font-bold text-red-400">Analysis Failed</h2>
              <p className="text-slate-400">{error}</p>
              <button onClick={() => setStatus(AnalysisStatus.IDLE)} className="w-full py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold transition-colors">
                Try Again
              </button>
            </div>
