import React, { useState, useCallback, useRef, useMemo, useEffect } from 'react';
import { AnalysisStatus, CritiqueResult, Session } from './types';
import { analyzeAudio, createChatSession } from './services/geminiService';
import Spectrogram from './components/Spectrogram';
import CritiqueSection from './components/CritiqueSection';
import ChatInterface from './components/ChatInterface';

const STORAGE_KEY = 'sonic_critique_sessions';

const App: React.FC = () => {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const globalFileInputRef = useRef<HTMLInputElement>(null);

  // Load sessions from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setSessions(parsed);
      } catch (e) {
        console.error("Failed to load sessions", e);
      }
    }
  }, []);

  // Save sessions to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  }, [sessions]);

  const currentSession = useMemo(() => 
    sessions.find(s => s.id === currentSessionId) || null
  , [sessions, currentSessionId]);

  const latestCritique = currentSession?.critiques[currentSession.critiques.length - 1] || null;

  const chatSession = useMemo(() => {
    if (latestCritique) return createChatSession(latestCritique);
    return null;
  }, [latestCritique]);

  const createNewSession = (initialName: string): Session => {
    const newSession: Session = {
      id: crypto.randomUUID(),
      name: initialName,
      createdAt: Date.now(),
      lastModified: Date.now(),
      critiques: [],
      latestFileName: initialName
    };
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    return newSession;
  };

  const processAudioFile = useCallback(async (file: File, sessionId: string, prevCritique: CritiqueResult | null) => {
    try {
      const isComparing = !!prevCritique;
      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.UPLOADING);

      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => {
          const result = reader.result as string;
          resolve(result.split(',')[1]);
        };
        reader.readAsDataURL(file);
      });

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const arrayBuffer = await file.arrayBuffer();
      const decodedBuffer = await audioCtx.decodeAudioData(arrayBuffer);
      setAudioBuffer(decodedBuffer);

      setStatus(isComparing ? AnalysisStatus.COMPARING : AnalysisStatus.ANALYZING_AI);
      const base64Audio = await base64Promise;

      // Use the provided previous critique for comparison context
      const result = await analyzeAudio(base64Audio, file.type, prevCritique || undefined);

      setSessions(prev => prev.map(s => {
        if (s.id === sessionId) {
          return {
            ...s,
            lastModified: Date.now(),
            latestFileName: file.name,
            critiques: [...s.critiques, result]
          };
        }
        return s;
      }));

      setStatus(AnalysisStatus.SUCCESS);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred during analysis.");
      setStatus(AnalysisStatus.ERROR);
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      let targetId = currentSessionId;
      let prevCritique = latestCritique;

      if (!targetId) {
        // If no project is selected, create a new one first
        const newSess = createNewSession(file.name);
        targetId = newSess.id;
        prevCritique = null;
      }

      // Pass ID and critique directly to avoid relying on state that's currently updating
      processAudioFile(file, targetId, prevCritique);
      e.target.value = '';
    }
  };

  const triggerUpload = () => globalFileInputRef.current?.click();

  const deleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    e.preventDefault();
    if (window.confirm("Delete this mix project? This cannot be undone.")) {
      setSessions(prev => prev.filter(s => s.id !== id));
      if (currentSessionId === id) {
        setCurrentSessionId(null);
        setStatus(AnalysisStatus.IDLE);
        setAudioBuffer(null);
      }
    }
  };

  const startNewProject = () => {
    setCurrentSessionId(null);
    setStatus(AnalysisStatus.IDLE);
    setAudioBuffer(null);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 flex relative">
      {/* Sidebar */}
      <aside className={`bg-slate-900 border-r border-slate-800 transition-all duration-300 flex flex-col z-40 ${isSidebarOpen ? 'w-72' : 'w-0 overflow-hidden'}`}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between whitespace-nowrap">
          <h2 className="font-bold text-slate-400 text-xs tracking-widest uppercase">Mix Projects</h2>
          <button onClick={startNewProject} className="p-2 hover:bg-slate-800 rounded-lg text-indigo-400 transition-colors" title="New Project">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto py-4">
          {sessions.length === 0 && (
            <div className="px-6 py-10 text-center text-slate-600 italic text-sm">No saved projects yet.</div>
          )}
          {sessions.map(s => (
            <div 
              key={s.id}
              onClick={() => {
                setCurrentSessionId(s.id);
                setStatus(s.critiques.length > 0 ? AnalysisStatus.SUCCESS : AnalysisStatus.IDLE);
                setAudioBuffer(null);
              }}
              className={`px-6 py-4 cursor-pointer border-l-4 transition-all hover:bg-slate-800/50 group flex items-center justify-between ${currentSessionId === s.id ? 'bg-indigo-600/10 border-indigo-500' : 'border-transparent'}`}
            >
              <div className="flex-1 truncate mr-2">
                <div className="font-bold text-sm truncate">{s.name}</div>
                <div className="text-[10px] text-slate-500 flex items-center mt-1">
                  <span>{new Date(s.lastModified).toLocaleDateString()}</span>
                  <span className="mx-2">•</span>
                  <span>{s.critiques.length} revision{s.critiques.length !== 1 ? 's' : ''}</span>
                </div>
              </div>
              <button 
                type="button"
                onClick={(e) => deleteSession(e, s.id)}
                className="opacity-40 group-hover:opacity-100 p-1.5 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
                title="Delete Project"
              >
                <svg className="w-4 h-4 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-h-screen">
        <header className="border-b border-slate-800 bg-slate-950/80 backdrop-blur-md sticky top-0 z-50">
          <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                </svg>
              </button>
              <div className="flex items-center space-x-3 cursor-pointer" onClick={startNewProject}>
                <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg">
                  <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" /></svg>
                </div>
                <h1 className="text-lg font-bold tracking-tight hidden sm:block">Sonic<span className="text-indigo-500">Critique</span> AI</h1>
              </div>
            </div>

            <div className="flex items-center space-x-4">
              {latestCritique && (
                <button 
                  onClick={() => setIsChatOpen(prev => !prev)}
                  className={`flex items-center space-x-2 px-4 py-1.5 rounded-full text-xs font-bold transition-all ${isChatOpen ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}`}
                >
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
                  <span>CHAT WITH ENGINEER</span>
                </button>
              )}
            </div>
          </div>
        </header>

        <main className="flex-1 max-w-7xl mx-auto px-6 py-12 w-full">
          {status === AnalysisStatus.IDLE && (
            <div className="max-w-2xl mx-auto text-center space-y-8 animate-in zoom-in duration-500 py-12">
              <div className="space-y-4">
                <h2 className="text-4xl md:text-5xl font-extrabold text-white">
                  Persistent <span className="text-indigo-500">Mix History</span>
                </h2>
                <p className="text-slate-400 text-lg leading-relaxed">
                  Start a new project or select a saved one from the sidebar. 
                  Every revision you upload is remembered, allowing the AI to track your progress.
                </p>
              </div>

              <div 
                onClick={triggerUpload}
                className="group relative cursor-pointer p-16 rounded-3xl border-2 border-dashed border-slate-800 bg-slate-900/30 hover:bg-slate-900/50 hover:border-indigo-500/50 transition-all duration-300"
              >
                <div className="flex flex-col items-center">
                  <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center mb-6 group-hover:bg-indigo-600 transition-colors">
                    <svg className="w-8 h-8 text-indigo-400 group-hover:text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                  </div>
                  <h3 className="text-xl font-bold mb-2">Upload First Revision</h3>
                  <p className="text-slate-500 italic">"The AI engineer never forgets a frequency."</p>
                </div>
              </div>
            </div>
          )}

          {(status !== AnalysisStatus.IDLE && status !== AnalysisStatus.ERROR) && (
            <div className="space-y-12">
              {status !== AnalysisStatus.SUCCESS && (
                <div className="max-w-md mx-auto text-center space-y-6 py-24">
                  <div className="relative">
                    <div className="w-20 h-20 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin mx-auto" />
                    <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 font-bold text-indigo-500">
                      {status === AnalysisStatus.COMPARING ? "VS" : "AI"}
                    </div>
                  </div>
                  <h3 className="text-xl font-bold text-white mb-2">
                    {status === AnalysisStatus.UPLOADING && "Scanning Waveform..."}
                    {status === AnalysisStatus.ANALYZING_AI && "Engineer Reviewing Mix..."}
                    {status === AnalysisStatus.COMPARING && "Contextualizing Progress..."}
                  </h3>
                </div>
              )}

              {status === AnalysisStatus.SUCCESS && latestCritique && (
                <div id="analysis-report-container" className="animate-in fade-in slide-in-from-bottom-6 duration-700 space-y-12 bg-slate-950 p-6 rounded-3xl">
                  <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-800 pb-8 mb-8">
                    <div>
                      <h2 className="text-3xl font-extrabold text-white mb-1">
                        {currentSession?.name}
                      </h2>
                      <p className="text-slate-500 font-medium">
                        Project History: {currentSession?.critiques.length} Revisions Saved
                      </p>
                    </div>
                    <div className="flex space-x-3 print:hidden">
                      <button onClick={triggerUpload} className="px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl text-sm font-bold transition-all shadow-lg shadow-emerald-500/20 active:scale-95">
                        Upload Next Revision
                      </button>
                    </div>
                  </div>

                  <CritiqueSection 
                    critique={latestCritique} 
                    fileName={currentSession?.latestFileName || 'Track'} 
                    onCompare={triggerUpload}
                    isComparison={currentSession!.critiques.length > 1}
                  />

                  {audioBuffer ? (
                    <Spectrogram audioBuffer={audioBuffer} />
                  ) : (
                    <div className="bg-slate-900/30 p-12 rounded-2xl border border-slate-800 text-center text-slate-500 italic">
                      Spectrogram is available for the current active upload.
                    </div>
                  )}

                  <div className="pt-12 text-center print:hidden">
                     <button 
                      onClick={() => setIsChatOpen(true)}
                      className="inline-flex items-center space-x-3 bg-indigo-600/10 border border-indigo-500/30 text-indigo-400 px-8 py-4 rounded-2xl hover:bg-indigo-600/20 transition-all font-bold"
                    >
                      <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
                      <span>Ask our Engineer about this revision</span>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {status === AnalysisStatus.ERROR && (
            <div className="max-w-lg mx-auto bg-red-950/20 border border-red-500/30 p-8 rounded-3xl text-center space-y-6">
              <h2 className="text-xl font-bold text-red-400">Analysis Failed</h2>
              <p className="text-slate-400">{error}</p>
              <button onClick={() => setStatus(AnalysisStatus.IDLE)} className="w-full py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold transition-colors">
                Try Again
              </button>
            </div>
          )}
        </main>
      </div>

      {chatSession && (
        <ChatInterface 
          session={chatSession} 
          isOpen={isChatOpen} 
          onClose={() => setIsChatOpen(false)} 
        />
      )}

      <input 
        type="file" 
        ref={globalFileInputRef} 
        onChange={handleFileChange} 
        className="hidden" 
        accept="audio/*" 
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Chat } from '@google/genai';
import { ChatMessage } from '../types';

interface ChatInterfaceProps {
  session: Chat;
  isOpen: boolean;
  onClose: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ session, isOpen, onClose }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [selectedImages, setSelectedImages] = useState<string[]>([]);
  const [isProcessingImage, setIsProcessingImage] = useState(false);

  // Resizing state for the chat window itself
  const [dimensions, setDimensions] = useState({ width: 384, height: 600 });
  const [isResizing, setIsResizing] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Resize handler for the window
  const startResizing = useCallback((e: React.PointerEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => {
    setIsResizing(false);
  }, []);

  const resize = useCallback((e: PointerEvent) => {
    if (!isResizing || !containerRef.current) return;
    const newWidth = window.innerWidth - e.clientX - 24;
    const newHeight = window.innerHeight - e.clientY - 24;
    setDimensions({
      width: Math.max(320, Math.min(newWidth, window.innerWidth - 48)),
      height: Math.max(400, Math.min(newHeight, window.innerHeight - 48))
    });
  }, [isResizing]);

  useEffect(() => {
    if (isResizing) {
      window.addEventListener('pointermove', resize);
      window.addEventListener('pointerup', stopResizing);
    } else {
      window.removeEventListener('pointermove', resize);
      window.removeEventListener('pointerup', stopResizing);
    }
    return () => {
      window.removeEventListener('pointermove', resize);
      window.removeEventListener('pointerup', stopResizing);
    };
  }, [isResizing, resize, stopResizing]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  /**
   * Resizes and compresses an image to prevent UI freezing
   * Targets max 1280px dimension and JPEG 0.8 quality
   */
  const processAndResizeImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const maxDim = 1280;

          if (width > height && width > maxDim) {
            height *= maxDim / width;
            width = maxDim;
          } else if (height > maxDim) {
            width *= maxDim / height;
            height = maxDim;
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject('Could not get canvas context');

          ctx.drawImage(img, 0, 0, width, height);
          // Use image/jpeg with 0.8 quality for significant file size reduction
          const compressedBase64 = canvas.toDataURL('image/jpeg', 0.8);
          resolve(compressedBase64);
        };
        img.onerror = reject;
        img.src = e.target?.result as string;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      setIsProcessingImage(true);
      try {
        const processed = await Promise.all(Array.from(files).map(processAndResizeImage));
        setSelectedImages(prev => [...prev, ...processed]);
      } catch (err) {
        console.error("Image processing failed:", err);
      } finally {
        setIsProcessingImage(false);
      }
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handlePaste = async (e: React.ClipboardEvent) => {
    const items = e.clipboardData.items;
    const imageFiles: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const file = items[i].getAsFile();
        if (file) imageFiles.push(file);
      }
    }

    if (imageFiles.length > 0) {
      setIsProcessingImage(true);
      try {
        const processed = await Promise.all(imageFiles.map(processAndResizeImage));
        setSelectedImages(prev => [...prev, ...processed]);
      } catch (err) {
        console.error("Paste processing failed:", err);
      } finally {
        setIsProcessingImage(false);
      }
    }
  };

  const removeImage = (index: number) => {
    setSelectedImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!input.trim() && selectedImages.length === 0) || isTyping || isProcessingImage) return;

    const userText = input.trim();
    const currentImages = [...selectedImages];

    setInput('');
    setSelectedImages([]);

    setMessages(prev => [...prev, { role: 'user', text: userText, images: currentImages.length > 0 ? currentImages : undefined }]);
    setIsTyping(true);

    try {
      const parts: any[] = [];
      if (userText) parts.push({ text: userText });
      else if (currentImages.length > 0) parts.push({ text: "Analyze these screenshots in the context of my mix." });

      currentImages.forEach(img => {
        const base64Data = img.split(',')[1];
        const mimeType = img.split(';')[0].split(':')[1];
        parts.push({ inlineData: { data: base64Data, mimeType } });
      });

      // Fix: chat.sendMessageStream expects a 'message' parameter that is string | Part | Part[].
      // DO NOT wrap the parts array in another object with a 'parts' key.
      const response = await session.sendMessageStream({ message: parts });
      let fullText = '';

      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of response) {
        const textChunk = chunk.text || '';
        fullText += textChunk;
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullText };
          return updated;
        });
      }
    } catch (error) {
      console.error('Chat error:', error);
      setMessages(prev => [...prev, { role: 'model', text: 'Sorry, I encountered an error processing that request.' }]);
    } finally {
      setIsTyping(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div 
      ref={containerRef}
      style={{ 
        width: `${dimensions.width}px`, 
        height: `${dimensions.height}px`,
        touchAction: 'none'
      }}
      className={`fixed bottom-6 right-6 bg-slate-900 border ${isResizing ? 'border-indigo-500 shadow-indigo-500/20' : 'border-slate-800'} rounded-3xl shadow-2xl flex flex-col z-[100] animate-in slide-in-from-bottom-10 duration-300 transition-colors`}
    >
      {/* Resize Handle - Top Left */}
      <div 
        onPointerDown={startResizing}
        className="absolute top-0 left-0 w-8 h-8 cursor-nwse-resize z-50 flex items-center justify-center group"
      >
        <div className="w-4 h-4 border-t-2 border-l-2 border-slate-700 group-hover:border-indigo-500 rounded-tl transition-colors m-2" />
      </div>

      <div className="p-4 pl-10 border-b border-slate-800 flex items-center justify-between bg-indigo-950/20 rounded-t-3xl select-none">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 20 20">
              <path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" />
            </svg>
          </div>
          <div>
            <h3 className="text-sm font-bold">Mixing Engineer Chat</h3>
            <p className="text-[10px] text-slate-400">Vision & Library Aware</p>
          </div>
        </div>
        <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors p-1">
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center py-10 px-4">
            <p className="text-slate-500 text-sm">Ask about your revision or paste/upload screenshots (EQ curves, plugins, analyzer) for visual feedback!</p>
          </div>
        )}
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-slate-800 text-slate-100 rounded-tl-none'}`}>
              {msg.images && msg.images.length > 0 && (
                <div className={`grid gap-2 mb-2 ${msg.images.length > 1 ? 'grid-cols-2' : 'grid-cols-1'}`}>
                  {msg.images.map((img, i) => (
                    <img key={i} src={img} alt="Attachment" className="rounded-lg w-full h-auto border border-white/10" />
                  ))}
                </div>
              )}
              <div className="whitespace-pre-wrap">{msg.text}</div>
            </div>
          </div>
        ))}
        {isTyping && messages.length > 0 && messages[messages.length-1].role === 'model' && messages[messages.length-1].text === '' && (
          <div className="flex justify-start">
            <div className="bg-slate-800 p-3 rounded-2xl rounded-tl-none flex space-x-1">
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
              <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSend} className="p-4 border-t border-slate-800 bg-slate-900/50 rounded-b-3xl">
        {(selectedImages.length > 0 || isProcessingImage) && (
          <div className="mb-3 flex flex-wrap gap-2 max-h-32 overflow-y-auto p-1">
            {selectedImages.map((img, idx) => (
              <div key={idx} className="relative group">
                <img src={img} alt="Preview" className="w-16 h-16 object-cover rounded-lg border-2 border-indigo-500 shadow-sm" />
                <button 
                  type="button"
                  onClick={() => removeImage(idx)}
                  className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-md hover:bg-red-600 transition-colors opacity-0 group-hover:opacity-100"
                >
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
            {isProcessingImage && (
              <div className="w-16 h-16 bg-slate-800 rounded-lg flex items-center justify-center animate-pulse border-2 border-dashed border-slate-700">
                <svg className="w-6 h-6 text-slate-600 animate-spin" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
              </div>
            )}
          </div>
        )}

        <div className="flex items-center space-x-2">
          <button 
            type="button"
            disabled={isProcessingImage}
            onClick={() => fileInputRef.current?.click()}
            className={`p-2 rounded-xl border transition-all ${selectedImages.length > 0 ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-white hover:border-slate-600'} disabled:opacity-50`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </button>

          <div className="relative flex-1">
            <input
              type="text"
              value={input}
              onPaste={handlePaste}
              disabled={isProcessingImage}
              onChange={(e) => setInput(e.target.value)}
              placeholder={isProcessingImage ? "Processing image..." : (selectedImages.length > 0 ? "Describe these..." : "Ask follow-up or paste...")}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl py-2.5 px-4 pr-12 text-sm focus:outline-none focus:border-indigo-500 transition-colors disabled:opacity-50"
            />
            <button 
              type="submit"
              disabled={isTyping || isProcessingImage}
              className="absolute right-2 top-1/2 -translate-y-1/2 text-indigo-500 hover:text-indigo-400 p-1 disabled:opacity-50"
            >
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </div>
        </div>

        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleImageSelect} 
          className="hidden" 
          accept="image/*" 
          multiple
        />
      </form>
    </div>
  );
};

